    if (item.type !== '' || item.size > MB) {
        return true;
    }

    return new Promise<void>((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = ({ target }) => {
            if (!target?.result) {
                return reject();
            }
            resolve();
        };
        reader.onerror = reject;
        reader.onabort = reject;
        reader.readAsBinaryString(item);
    })
        .then(() => true)
        .catch(() => false);
};

